class Solution {vector<int>occ(const string&s,const string&p){int n=s.size(),m=p.size();vector<int>v(n+1);if(!m){iota(v.begin(),v.end(),0);return v;}vector<int>pi(m);for(int i=1,j=0;i<m;++i){while(j&&p[i]!=p[j])j=pi[j-1];if(p[i]==p[j])++j;pi[i]=j;}for(int i=0,j=0;i<n;++i){while(j&&s[i]!=p[j])j=pi[j-1];if(s[i]==p[j])++j;if(j==m){v[i-m+1]=1;j=pi[j-1];}}return v;}
 public:int shortestMatchingSubstring(string s,string p){int a=p.find('*'),b=p.find('*',a+1);string x=p.substr(0,a),y=p.substr(a+1,b-a-1),z=p.substr(b+1);int n=s.size();auto A=occ(s,x),B=occ(s,y),C=occ(s,z);vector<int>nb(n+2,n+1),nc(n+2,n+1);for(int i=n;i>=0;--i){nb[i]=B[i]?i:nb[i+1];nc[i]=C[i]?i:nc[i+1];}int ans=INT_MAX;for(int i=0;i+(int)x.size()<=n;++i)if(A[i]){int j=nb[i+x.size()];if(j>n)continue;int t=nc[j+y.size()];if(t<=n)ans=min(ans,t+(int)z.size()-i);}return ans==INT_MAX?-1:ans;
 }};
